module bond_assignment (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [127:0] prob,\n    output reg [31:0] max_product,\n    output reg done\n);\n\n    // State machine declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] COMPUTE = 3'd2;\n    localparam [2:0] FINISH = 3'd3;\n    reg [2:0] state, next_state;\n\n    // DP state storage\n    reg [31:0] dp [0:15];\n    integer i;\n\n    // Current processing state\n    reg [3:0] current_mask;\n    reg [1:0] current_agent;\n    reg [1:0] current_mission;\n\n    // Lookup table for number of set bits in 4-bit mask\n    reg [1:0] set_bits [0:15];\n    initial begin\n        set_bits[0] = 2'd0;  set_bits[1] = 2'd1;  set_bits[2] = 2'd1;  set_bits[3] = 2'd2;\n        set_bits[4] = 2'd1;  set_bits[5] = 2'd2;  set_bits[6] = 2'd2;  set_bits[7] = 2'd3;\n        set_bits[8] = 2'd1;  set_bits[9] = 2'd2;  set_bits[10] = 2'd2; set_bits[11] = 2'd3;\n        set_bits[12] = 2'd2; set_bits[13] = 2'd3; set_bits[14] = 2'd3; set_bits[15] = 2'd4;\n    end\n\n    // Unpack probabilities into 4x4 matrix\n    wire [7:0] prob_matrix [0:3][0:3];\n    assign prob_matrix[0][0] = prob[7:0];    assign prob_matrix[0][1] = prob[15:8];\n    assign prob_matrix[0][2] = prob[23:16];  assign prob_matrix[0][3] = prob[31:24];\n    assign prob_matrix[1][0] = prob[39:32];  assign prob_matrix[1][1] = prob[47:40];\n    assign prob_matrix[1][2] = prob[55:48];  assign prob_matrix[1][3] = prob[63:56];\n    assign prob_matrix[2][0] = prob[71:64];  assign prob_matrix[2][1] = prob[79:72];\n    assign prob_matrix[2][2] = prob[87:80];  assign prob_matrix[2][3] = prob[95:88];\n    assign prob_matrix[3][0] = prob[103:96]; assign prob_matrix[3][1] = prob[111:104];\n    assign prob_matrix[3][2] = prob[119:112];assign prob_matrix[3][3] = prob[127:120];\n\n    // State transition logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start) next_state = INIT;\n                else next_state = IDLE;\n            end\n            INIT: next_state = COMPUTE;\n            COMPUTE: begin\n                if (current_mask == (1 << N) - 1) next_state = FINISH;\n                else next_state = COMPUTE;\n            end\n            FINISH: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // State register with reset\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_product <= 32'd0;\n            current_mask <= 4'd0;\n            current_agent <= 2'd0;\n            current_mission <= 2'd0;\n            for (i = 0; i < 16; i = i + 1) dp[i] <= 32'd0;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Main computation logic\n    always @(posedge clk) begin\n        case (state)\n            INIT: begin\n                for (i = 0; i < 16; i = i + 1) dp[i] <= 32'd0;\n                dp[0] <= 32'd1;\n                current_mask <= 4'd0;\n                current_agent <= 2'd0;\n                current_mission <= 2'd0;\n                done <= 1'b0;\n            end\n            COMPUTE: begin\n                if (current_mask < (1 << N) - 1) begin\n                    if (set_bits[current_mask] == current_agent) begin\n                        if (current_mission < N) begin\n                            if (!current_mask[current_mission]) begin\n                                reg [3:0] new_mask;\n                                reg [31:0] product;\n                                new_mask = current_mask | (1 << current_mission);\n                                product = dp[current_mask] * prob_matrix[current_agent][current_mission];\n                                if (product > dp[new_mask]) begin\n                                    dp[new_mask] <= product;\n                                end\n                            end\n                            current_mission <= current_mission + 1;\n                        end else begin\n                            current_mask <= current_mask + 1;\n                            current_mission <= 2'd0;\n                            if (current_agent < N - 1) begin\n                                current_agent <= current_agent + 1;\n                            end\n                        end\n                    end else begin\n                        current_mask <= current_mask + 1;\n                        current_mission <= 2'd0;\n                    end\n                end\n            end\n            FINISH: begin\n                max_product <= dp[(1 << N) - 1];\n                done <= 1'b1;\n            end\n        endcase\n    end\nendmodule